-- Ariovelle foundation schema, migration 0001.
-- Apply only to an explicitly provisioned NON-PRODUCTION development database.
-- This file is not executed by CI and does not provision or connect to a database.
-- PostgreSQL 15+ recommended. UUIDs are generated by the application.
BEGIN;

CREATE TABLE users (
  id UUID PRIMARY KEY,
  status TEXT NOT NULL DEFAULT 'active'
    CHECK (status IN ('active', 'suspended', 'deletion_pending')),
  display_name TEXT,
  primary_email TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE external_identities (
  id UUID PRIMARY KEY,
  user_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  provider TEXT NOT NULL,
  issuer TEXT NOT NULL,
  subject TEXT NOT NULL,
  email_snapshot TEXT,
  email_verified BOOLEAN,
  linked_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_authenticated_at TIMESTAMPTZ,
  CONSTRAINT external_identities_provider_issuer_subject_uq
    UNIQUE (provider, issuer, subject),
  CONSTRAINT external_identities_provider_nonempty CHECK (length(trim(provider)) > 0),
  CONSTRAINT external_identities_issuer_nonempty CHECK (length(trim(issuer)) > 0),
  CONSTRAINT external_identities_subject_nonempty CHECK (length(trim(subject)) > 0)
);
CREATE INDEX external_identities_user_id_idx ON external_identities(user_id);

CREATE TABLE user_profiles (
  user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE RESTRICT,
  first_name TEXT,
  last_name TEXT,
  avatar_url TEXT,
  locale TEXT,
  timezone TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE user_preferences (
  user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE RESTRICT,
  theme TEXT NOT NULL DEFAULT 'system'
    CHECK (theme IN ('dark', 'light', 'system')),
  base_currency CHAR(3),
  timezone TEXT,
  locale TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT user_preferences_currency_format
    CHECK (base_currency IS NULL OR base_currency ~ '^[A-Z]{3}$')
);

CREATE TABLE workspaces (
  id UUID PRIMARY KEY,
  type TEXT NOT NULL CHECK (type IN ('personal', 'business')),
  name TEXT NOT NULL CHECK (length(trim(name)) > 0),
  owner_user_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  status TEXT NOT NULL DEFAULT 'active'
    CHECK (status IN ('active', 'suspended', 'archived')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX workspaces_one_personal_per_owner_uq
  ON workspaces(owner_user_id) WHERE type = 'personal';
CREATE INDEX workspaces_owner_user_id_idx ON workspaces(owner_user_id);

CREATE TABLE workspace_memberships (
  id UUID PRIMARY KEY,
  workspace_id UUID NOT NULL REFERENCES workspaces(id) ON DELETE RESTRICT,
  user_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  role TEXT NOT NULL CHECK (role IN ('owner', 'admin', 'member', 'viewer')),
  status TEXT NOT NULL DEFAULT 'active'
    CHECK (status IN ('invited', 'active', 'suspended', 'removed')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT workspace_memberships_workspace_user_uq UNIQUE (workspace_id, user_id)
);
CREATE INDEX workspace_memberships_user_status_idx
  ON workspace_memberships(user_id, status);
CREATE INDEX workspace_memberships_workspace_status_idx
  ON workspace_memberships(workspace_id, status);

CREATE TABLE audit_events (
  id UUID PRIMARY KEY,
  actor_user_id UUID REFERENCES users(id) ON DELETE RESTRICT,
  workspace_id UUID REFERENCES workspaces(id) ON DELETE RESTRICT,
  action TEXT NOT NULL CHECK (length(trim(action)) > 0),
  entity_type TEXT,
  entity_id TEXT,
  request_id TEXT,
  metadata JSONB NOT NULL DEFAULT '{}'::jsonb
    CHECK (jsonb_typeof(metadata) = 'object'),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX audit_events_workspace_created_idx
  ON audit_events(workspace_id, created_at DESC);
CREATE INDEX audit_events_actor_created_idx
  ON audit_events(actor_user_id, created_at DESC);

-- Tracks import provenance and makes future migration batches idempotent.
-- No legacy Firebase records are imported by this migration.
CREATE TABLE migration_batches (
  id UUID PRIMARY KEY,
  source_system TEXT NOT NULL,
  source_version TEXT,
  status TEXT NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending', 'running', 'completed', 'completed_with_errors', 'failed', 'rolled_back')),
  started_at TIMESTAMPTZ,
  completed_at TIMESTAMPTZ,
  source_record_count BIGINT NOT NULL DEFAULT 0 CHECK (source_record_count >= 0),
  imported_record_count BIGINT NOT NULL DEFAULT 0 CHECK (imported_record_count >= 0),
  rejected_record_count BIGINT NOT NULL DEFAULT 0 CHECK (rejected_record_count >= 0),
  source_checksum TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE migration_records (
  id UUID PRIMARY KEY,
  batch_id UUID NOT NULL REFERENCES migration_batches(id) ON DELETE RESTRICT,
  source_system TEXT NOT NULL,
  source_owner_key TEXT NOT NULL,
  source_collection TEXT NOT NULL,
  source_record_id TEXT NOT NULL,
  target_table TEXT,
  target_record_id UUID,
  source_checksum TEXT NOT NULL,
  status TEXT NOT NULL
    CHECK (status IN ('pending', 'imported', 'skipped', 'rejected', 'conflict')),
  error_code TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT migration_records_source_identity_uq
    UNIQUE (source_system, source_owner_key, source_collection, source_record_id)
);
CREATE INDEX migration_records_batch_status_idx
  ON migration_records(batch_id, status);

COMMIT;

-- Operational hardening is intentionally separate from this portable schema:
-- * Create separate migration-owner and runtime roles; runtime gets least privilege.
-- * Grant SELECT/INSERT/UPDATE as needed; deny UPDATE/DELETE on audit_events to runtime.
-- * Add RLS policies only after the transaction-local verified-user/workspace context
--   mechanism is implemented and tested. Never trust a client-supplied workspace ID.
-- * Add database backup/PITR and retention settings at the provider layer.
